command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="eccc723ce730b49be79626cf2e5794d1e2a9fabc"
$candidate="3937e796b0a9017b747fc2010e38cf129661caa0"
$branch="work/metadata-sort-correctness-20261006"
$temp=Join-Path $env:RUNNER_TEMP ("fly-metadata-sort-vm-"+$env:GITHUB_RUN_ID)
$evidence=Join-Path $repo "logs\remote-evidence"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "metadata sort VM fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before metadata sort VM acceptance"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "metadata sort candidate branch moved"}
if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp 2>$null; Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "metadata sort VM worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "metadata sort VM diff check failed"}
  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "metadata sort VM Release build failed"}
  $exe=Join-Path $temp "out\winui\Release\flyExplorer.exe"
  if(!(Test-Path -LiteralPath $exe -PathType Leaf)){throw "metadata sort VM executable missing"}
  & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --exe $exe --capture after
  if($LASTEXITCODE -ne 0){throw "metadata sort VM GUI acceptance failed"}
  foreach($leaf in @("flyExplorer.exe","FlyShellIsolationHelper.exe","flyExplorer.pri","MainWindow.xbf")){
    $path=Join-Path (Join-Path $temp "out\winui\Release") $leaf
    if(!(Test-Path -LiteralPath $path -PathType Leaf)){throw "metadata sort VM runtime file missing: $leaf"}
  }
  $shot=Join-Path $temp "logs\metadata-sort\metadata-sort-after.png"
  if(!(Test-Path -LiteralPath $shot -PathType Leaf)){throw "metadata sort VM AFTER screenshot missing"}
  New-Item -ItemType Directory -Path $evidence -Force | Out-Null
  Copy-Item -LiteralPath $shot -Destination (Join-Path $evidence "metadata-sort-after.png") -Force
  Write-Host "METADATA_SORT_VM_RELEASE=PASS"
  Write-Host "METADATA_SORT_VM_GUI=PASS"
  Write-Host "METADATA_SORT_VM_VISUAL=EXPORTED"
} finally {
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
